// Pawn Champ - The Collector from Boston: a buyer with a blank check, and the oldest trick in the trade.
// Major quest M36, batch R, round 2 (docs/quests/MAJOR.md#m36-the-collector-from-boston-crime).
// Stay-on only: from month 3 (December), and only for a shop that's a Trusted Dealer or better.
//
// Hook (W1 Tue-Thu)          Lucian Fairbairn, a Newbury Street dealer, wants Theodora Vail's "Slack Water"
//                            and will pay $600 for it. He's at the Harborview Motor Inn.
// Middle (shop)              Clem Tibbetts brings in a "Slack Water" that was his grandmother's (W2).
//                            Marv Kettle has cleared a Vail house before, and has a story about it (W2-W3).
// Scene 1 (W3 Tue-Thu)       the Harborview, out of season: one lit room, two men and a stack of paintings.
// Finale (W4)                Dot's Clam Shack at dusk: they're working the same trick on Dot.
// The fiddle game: the "collector" never comes back, and the seller was his partner all along.
//
// Written as data: docs/STORY_DATA.md. Strict JSON inside the call.

text:
// Pawn Champ - The Collector from Boston: a buyer with a blank check, and the oldest trick in the trade.
// Major quest M36, batch R, round 2 (docs/quests/MAJOR.md#m36-the-collector-from-boston-crime).
// Stay-on only: from month 3 (December), and only for a shop that's a Trusted Dealer or better.
//
// Hook (W1 Tue-Thu)          Lucian Fairbairn, a Newbury Street dealer, wants Theodora Vail's "Slack Water"
//                            and will pay $600 for it. He's at the Harborview Motor Inn.
// Middle (shop)              Clem Tibbetts brings in a "Slack Water" that was his grandmother's (W2).
//                            Marv Kettle has cleared a Vail house before, and has a story about it (W2-W3).
// Scene 1 (W3 Tue-Thu)       the Harborview, out of season: one lit room, two men and a stack of paintings.
// Finale (W4)                Dot's Clam Shack at dusk: they're working the same trick on Dot.
// The fiddle game: the "collector" never comes back, and the seller was his partner all along.
//
// Written as data: docs/STORY_DATA.md. Strict JSON inside the call.
defineStory({
  "id": "collector",
  "kind": "major",
  "colour": "#7a5a2a",
  "family": "crime",
  "title": "The Collector from Boston",
  "from": 3,
  "requires": "hook.trustedDealer",
  "rumour": "A dealer from Boston with a blank check, looking for one particular painting.",
  "endings": { "exposed": "The Fiddle Game", "cheque": "Blank Check", "stung": "Hung on the Wall", "passed": "Not My Line" },
  "about": [
    "A con story. Lucian Fairbairn, a Boston dealer staying at the shut-for-winter Harborview, will pay $600 for \"Slack Water\", a 1911 harbor painting by Theodora Vail that vanished into a Hollow Neck house (§{colFairbairn}). Days later Clem Tibbetts brings one in from his nan's Cliff Road house, asking $300 (§{colClem}).",
    "Marv tells you Gordie has bought one too, and that Vail's niece had six identical copies she sold to summer people; yours has a fresh canvas (§{colMarv}). If you passed on Clem's painting, that's where it ends (Not My Line). If you bought it, room six at the Harborview (§{colInn}) shows Fairbairn and Clem together with four more wet \"Slack Waters\", planning Dot's Clam Shack next.",
    "At Dot's at dusk (§{colShack}) the two run the fiddle game on her. Call Captain Barrow if you have a friend on the force (The Fiddle Game); hold up your copy and make Fairbairn pay his $600 in front of Dot (Blank Check); or warn Dot quietly and keep your painting as a lesson (Hung on the Wall)."
  ],
  "cast": {
    "fairbairn": {
      "name": "Lucian Fairbairn",
      "look": { "skin": "#f0d0b8", "hair": "#c8c8c8", "hs": 4, "coat": "#2a3a2e", "trim": "#e8e0c8", "style": "suit", "long": true, "pants": "#2a2a30", "glasses": "#c8a050", "bag": "#5a3a1e" }
    },
    "clem": {
      "name": "Clem Tibbetts",
      "look": { "skin": "#e0b090", "hair": "#6a4a2a", "hs": 1, "coat": "#5a6a4a", "style": "puffer", "pants": "#3a3a3a", "hat": "beanie", "hatc": "#c84a3a" }
    }
  },
  "uniques": {
    "slackWater": {
      "name": "Oil painting, \"Slack Water\", signed T. Vail",
      "icon": "painting",
      "cat": "art",
      "guide": 35,
      "condLabel": "Varnish still tacky",
      "tells": [
        "Boats on a still harbor at dusk, signed T. VAIL 1911 in the corner.",
        "The canvas is new and the stretcher bars are clean pine. The varnish is still a little tacky in the corners.",
        "On the back, a gallery label from Fairbairn & Lowe, Newbury Street, with the date scratched off."
      ]
    }
  },
  "scenes": {
    "colFairbairn": {
      "title": "Lucian Fairbairn wants \"Slack Water\"",
      "customer": "fairbairn",
      "steps": [
        { "say": "fairbairn", "text": "Lucian Fairbairn, Fairbairn & Lowe, Newbury Street. I asked around Boston for an honest shop on this stretch of coast. Everybody said yours." },
        { "view": { "counterIcon": "painting" } },
        { "narrate": "He lays a photograph on the counter: a small oil of boats on a still harbor at dusk." },
        {
          "say": "fairbairn",
          "text": [
            "Theodora Vail painted Hollow Neck in 1911. \"Slack Water.\" It went into a house here in the fifties and never came out. I have a client who wants it very badly.",
            "Six hundred dollars, cash or certified check, to whoever puts it in my hands. I'm at the Harborview till the month's out. Room six."
          ]
        },
        { "view": { "counterIcon": null } },
        {
          "choose": [
            {
              "label": "\"I'll keep an eye out.\"",
              "then": [
                { "set": { "colWatching": true } },
                { "say": "fairbairn", "text": "Splendid. I knew I'd come to the right shop." }
              ]
            },
            {
              "label": "\"Who stays at the Harborview in winter?\"",
              "then": [
                { "set": { "colAsked": true } },
                { "say": "fairbairn", "text": "A man who likes quiet, and doesn't like Boston prices. Keep an eye out, would you?" }
              ]
            },
            {
              "label": "\"Paintings aren't my line.\"",
              "then": [
                { "say": "fairbairn", "text": "Everything is everyone's line, at six hundred dollars. My card." }
              ]
            }
          ]
        },
        { "set": { "colMet": true } },
        { "leave": "fairbairn" }
      ]
    },
    "colClem": {
      "title": "Clem Tibbetts brings in his nan's painting",
      "customer": "clem",
      "steps": [
        { "say": "clem", "text": "Clem Tibbetts. I'm clearing my nan's place out on Cliff Road. This was over her telly for fifty years." },
        { "narrate": "Boats on a still harbor at dusk. Signed T. VAIL 1911 in the corner." },
        { "narrate": "You think about a man who likes quiet, staying at a motel that shut for the winter.", "if": "flag.colAsked" },
        { "say": "clem", "text": "I need it gone before the movers come. Someone said it might be worth something. I'd take three hundred." },
        {
          "offer": { "unique": "slackWater" },
          "persona": "desperate",
          "asking": 300,
          "min": 180,
          "onWatch": "continue"
        },
        {
          "if": "offer == 'watch'",
          "then": [{ "set": { "colEnd": "exposed", "colDone": true } }, { "end": true }]
        },
        {
          "if": "offer == 'deal'",
          "then": [
            { "set": { "colBought": true } },
            { "find": "slack", "in": "stock", "match": { "uniqueId": "slackWater" } },
            { "edit": "slack", "set": { "questKey": true, "nosale": true } },
            { "narrate": "When he's gone you ring the Harborview and ask for room six. The phone rings and rings." }
          ],
          "else": [
            { "set": { "colPassed": true } },
            { "say": "clem", "text": "Right. There's a car dealer on Route 1 who buys anything. I'll try him." }
          ]
        },
        { "leave": "clem" }
      ]
    },
    "colMarv": {
      "title": "Marv has seen six of them",
      "customer": "marv",
      "steps": [
        { "say": "marv", "text": "You'll like this. Gordie's bought a painting. Gordie. Boats at dusk, signed Vail. He's got it in the showroom between the Chevys." },
        { "say": "marv", "if": "flag.colBought", "text": "Hang on. That's the same picture you've got behind the counter." },
        {
          "say": "marv",
          "text": [
            "I cleared Theodora Vail's niece's house in 2009. In the shed there were six \"Slack Waters\", every one the same, never framed. She painted them for the summer people at five dollars a go.",
            "And yours has a fresh canvas. Somebody's been painting them again."
          ]
        },
        { "set": { "colMarv": true } },
        {
          "if": "flag.colPassed",
          "then": [
            { "say": "marv", "text": "Gordie paid three-fifty for his. His Boston man's checked out of the Harborview, of course. Gordie says it's an investment now. Gordie says that a lot." },
            { "set": { "colEnd": "passed", "colDone": true } }
          ]
        },
        { "leave": "marv" }
      ]
    },
    "colInn": {
      "title": "Room six at the Harborview",
      "music": "caper",
      "steps": [
        { "hook": "harborviewRoom", "with": 6 },
        {
          "stage": "motorinn",
          "actors": [{ "id": "you", "cast": "keeper", "name": "You", "at": [120, 164] }]
        },
        {
          "narrate": [
            "The Harborview Motor Inn, shut since Columbus Day. Snow on the walkway, snow in the pool, half the letters on the sign dead. One window is lit. Room six.",
            "You meant to knock. Through the gap in the curtain you see Lucian Fairbairn in his shirtsleeves, counting money onto the bed, and Clem Tibbetts eating a sandwich over the sink.",
            "Against the wall, face out, there are four more \"Slack Waters\", identical, the varnish still shining."
          ]
        },
        {
          "choose": [
            {
              "label": "Listen at the window",
              "then": [
                {
                  "narrate": [
                    "\"The clam shack, Thursday,\" Fairbairn is saying. \"The woman who runs it has a wall of harbor pictures. You go in first, I come in for chowder.\"",
                    "\"And the car dealer?\" \"Paid. Framed it. Calls it an investment.\" They both laugh."
                  ]
                },
                { "set": { "colOverheard": true } }
              ]
            },
            { "label": "Leave before anybody sees you" }
          ]
        },
        { "narrate": "You walk back to town in the snow. Room six's light goes off behind you." },
        { "set": { "colSeen": true } },
        { "toast": "Calendar: Dot's Clam Shack, Thursday at dusk", "look": "dot" }
      ]
    },
    "colShack": {
      "title": "Chowder at dusk at Dot's",
      "music": "tension",
      "steps": [
        {
          "stage": "clamshackDusk",
          "actors": [
            { "id": "you", "cast": "keeper", "name": "You", "at": [100, 164] },
            { "id": "dot", "cast": "dot", "at": [160, 160], "facingLeft": true },
            { "id": "clem", "cast": "clem", "at": [200, 164], "facingLeft": true }
          ]
        },
        { "narrate": "Dot's Clam Shack at dusk, the fryers ticking as they cool. Clem Tibbetts is at the counter with a painting under his arm, telling Dot about his nan." },
        { "say": "dot", "text": "Oh, I don't know. It is lovely. Three hundred, though." },
        { "narrate": "The door goes. Lucian Fairbairn, in a good coat, asking for a cup of chowder and looking at Dot's wall of harbor pictures as if he's never seen one before." },
        { "enter": { "id": "fairbairn", "cast": "fairbairn", "at": [240, 164], "facingLeft": true } },
        { "find": "slack", "in": "stock", "match": { "uniqueId": "slackWater" } },
        {
          "choose": [
            {
              "label": "Step outside and call Captain Barrow",
              "hint": { "if": "ally.police", "then": "({ally.police.name} is already dialling)" },
              "note": "ally.police: a regular you're friends with who can call the police (js/standing.js), or nothing",
              "then": [
                { "enter": { "id": "barrow", "cast": "barrow", "at": [60, 164] } },
                { "narrate": "Barrow comes in ten minutes later, stamping the snow off, and orders chowder too. Then she asks Mr. Fairbairn for his card, and asks Clem whose nan it was." },
                { "say": "barrow", "text": "Five \"Slack Waters\" in a motel room, a car dealer out three-fifty and a pawnshop out more. That's the fiddle game, gentlemen. Older than both of you." },
                { "take": "slack" },
                { "hook": "refund", "note": "gives back what you paid for the painting, if you paid anything" },
                { "heat": -10 },
                { "rep": 4, "why": "Caught the Boston con men at Dot's" },
                { "say": "dot", "text": "I was going to hang it over the fryer. Lord." },
                { "set": { "colEnd": "exposed" } }
              ]
            },
            {
              "label": "Hold up your own \"Slack Water\" and offer it to Fairbairn, out loud, for his $600",
              "hint": "(he can't say no in front of Dot)",
              "if": "slack",
              "then": [
                { "say": "you", "text": "Mr. Fairbairn! You were after \"Slack Water\". I found it for you. $600, wasn't it?" },
                { "narrate": "Dot looks at him. Clem looks at him. Fairbairn looks at the painting he had painted, and then at the woman whose wall he wanted, and takes out a check book." },
                { "say": "fairbairn", "text": "So it was. How very efficient you are." },
                { "take": "slack" },
                { "coin": 600, "why": "Sold \"Slack Water\" back to Lucian Fairbairn" },
                { "narrate": "You're at the bank when it opens. The check clears. Room six is empty by noon, and Clem never comes back for his three hundred." },
                { "set": { "colEnd": "cheque" } }
              ]
            },
            {
              "label": "Tell Dot quietly not to buy, and let them go",
              "then": [
                {
                  "narrate": [
                    "You lean over the counter and say three words to Dot. She says \"Oh!\" and then, louder, \"No thank you, hon.\"",
                    "Clem and Fairbairn leave separately, a minute apart, and drive off together. Your \"Slack Water\" goes up on the wall behind your counter, where it looks very nice."
                  ]
                },
                {
                  "if": "slack",
                  "then": [
                    { "edit": "slack", "set": { "questKey": false, "nosale": false } },
                    { "refresh": "panel" }
                  ]
                },
                { "sway": "dot", "by": 1, "why": "You warned her about the painting" },
                { "set": { "colEnd": "stung" } }
              ]
            }
          ]
        },
        { "set": { "colDone": true } }
      ]
    }
  },
  "beats": [
    { "drift": "col-hook", "from": "1-2", "to": "1-4", "cast": "fairbairn", "scene": "colFairbairn" },
    { "drift": "col-clem", "from": "2-1", "to": "2-3", "cast": "clem", "scene": "colClem", "if": "flag.colMet && !flag.colDone && shelf.free" },
    { "drift": "col-marv", "from": "2-4", "to": "3-1", "cast": "marv", "scene": "colMarv", "if": "(flag.colBought || flag.colPassed) && !flag.colDone" }
  ],
  "nights": [
    {
      "id": "col-inn",
      "window": ["3-2", "3-4"],
      "if": "flag.colBought && !flag.colDone",
      "scene": "colInn",
      "test": [{ "set": { "colBought": true } }, { "add": { "unique": "slackWater" } }]
    },
    {
      "id": "col-shack",
      "window": ["4-1", "4-4"],
      "if": "flag.colSeen && !flag.colDone",
      "scene": "colShack",
      "test": [
        { "set": { "colSeen": true } },
        { "add": { "unique": "slackWater" }, "as": "it" },
        { "edit": "it", "set": { "paid": 250 } }
      ]
    }
  ],
  "calendar": [
    { "id": "col-inn", "night": "col-inn", "story": "collector", "where": "The Harborview Motor Inn", "title": "Room six", "known": "flag.colBought", "scene": "colInn" },
    { "id": "col-shack", "night": "col-shack", "story": "collector", "where": "Dot's Clam Shack", "title": "Chowder at dusk", "known": "flag.colSeen", "scene": "colShack" }
  ],
  "epilogue": [
    { "line": "Lucian Fairbairn and Clem Tibbetts are wanted in three states for the fiddle game. Dot has a newspaper photo of them on the clam shack wall, where the painting would have gone.", "if": "flag.colEnd == 'exposed'" },
    { "line": "Somewhere a gallery on Newbury Street has a gap in its books exactly the size of a \"Slack Water\". You bought the shop a new space heater with it.", "if": "flag.colEnd == 'cheque'" },
    { "line": "\"Slack Water\" hangs behind your counter. Customers ask about it. You tell them it's a lesson, and they think you mean art.", "if": "flag.colEnd == 'stung'" },
    { "line": "Gordie Haines still has his \"Slack Water\" in the showroom at Haines Motors, between the Chevys. It is not for sale. It is an investment.", "if": "flag.colEnd == 'passed'" }
  ],
  "outcome": "flag.colEnd"
});
